   "weekly_progress": "1.进度总：\n红书 出街21条内容，发布进度52.5%。投流进度20.64%，累计消耗¥22.49w，声量达成15.15w，总gmv达成10.5w；\n抖音 定号25/50，整体进度正常，预计下下周闭环定号工作\n\n2.数据指标达成：红书进店成本53.94 ROI 0.52，爆文率11%\n\n3.核心卡点or需支持项：样机发货延迟，导致抖音侧内容出街节奏偏慢，预计11.2恢复寄样，需要根据实际情况重新调整投流规划\n\n周度优质内容：\n小红书-低CPUV口径\n1. 一元one（9.18）内容方向-热门翻唱植入-唱播/录唱干货分享；\n2.mokia不是块小饼干（6.74）内容方向-热门翻唱植入-好物分享；\n3.木头澈（9.02）内容方向-热门翻唱植入-唱播/录唱干货分享；\n抖音-低cpA3口径；抖音-低cpA3口径-暂无",
   "weekly_focus": "1. 内容出街：红书推进至40篇内容全部发布，抖音定号持续跟进，预计下下周50个定号闭环\n2.投流侧：\n-红书消耗推进至32%\n-针对搜索版位其他词包消耗跑不出去问题进行单独搭建优化\n-测试新出街的优质素材\n3.首销双周复盘\n11.4提交复盘至gtm的文档内https://alidocs.dingtalk.com/i/nodes/a9E05BDRVQNdK1gXsPMdR2qmJ63zgkYA?utm_scene=person_space",
